namespace DocSummary.Models;

public class SummarizeRequest
{
    public required string DocumentText { get; set; }
    public int MaxSentences { get; set; } = 3;
}

namespace DocSummary.Models;

public class SummarizeResponse
{
    public required string Summary { get; set; }
    public int OriginalLength { get; set; }
    public int SummaryLength { get; set; }
}

using DocSummary.Models;

namespace DocSummary.Services;

public interface IDocumentSummaryService
{
    SummarizeResponse Summarize(SummarizeRequest request);
}

using DocSummary.Models;

namespace DocSummary.Services;

public class ExtractiveSummaryService : IDocumentSummaryService
{
    public SummarizeResponse Summarize(SummarizeRequest request)
    {
        var text = request.DocumentText.Trim();
        var sentences = SplitSentences(text);
        var maxSentences = Math.Clamp(request.MaxSentences, 1, sentences.Length);

        // Score sentences by word frequency relevance
        var wordFrequencies = GetWordFrequencies(sentences);
        var scored = sentences
            .Select((sentence, index) => (Sentence: sentence, Score: ScoreSentence(sentence, wordFrequencies), Index: index))
            .OrderByDescending(s => s.Score)
            .Take(maxSentences)
            .OrderBy(s => s.Index)
            .Select(s => s.Sentence);

        var summary = string.Join(" ", scored);

        return new SummarizeResponse
        {
            Summary = summary,
            OriginalLength = text.Length,
            SummaryLength = summary.Length
        };
    }

    private static string[] SplitSentences(string text)
    {
        return text.Split(['.', '!', '?'], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                   .Where(s => s.Length > 0)
                   .Select(s => s + ".")
                   .ToArray();
    }

    private static Dictionary<string, int> GetWordFrequencies(string[] sentences)
    {
        var frequencies = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var sentence in sentences)
        {
            foreach (var word in GetWords(sentence))
            {
                frequencies.TryGetValue(word, out var count);
                frequencies[word] = count + 1;
            }
        }
        return frequencies;
    }

    private static double ScoreSentence(string sentence, Dictionary<string, int> wordFrequencies)
    {
        var words = GetWords(sentence);
        if (words.Length == 0) return 0;
        return words.Sum(w => wordFrequencies.GetValueOrDefault(w, 0)) / (double)words.Length;
    }

    private static string[] GetWords(string text)
    {
        return text.Split([' ', ',', ';', ':', '"', '\'', '(', ')', '[', ']', '\n', '\r', '\t'],
                          StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                   .Where(w => w.Length > 2)
                   .ToArray();
    }
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummaryController : ControllerBase
{
    private readonly IDocumentSummaryService _summaryService;

    public SummaryController(IDocumentSummaryService summaryService)
    {
        _summaryService = summaryService;
    }

    [HttpPost]
    public ActionResult<SummarizeResponse> Summarize([FromBody] SummarizeRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.DocumentText))
        {
            return BadRequest(new { error = "DocumentText is required and cannot be empty." });
        }

        var result = _summaryService.Summarize(request);
        return Ok(result);
    }
}

